style.css:
@-moz-document domain("bandlab.com") {
/* --- FL Studio Color Palette Variables --- */
    :root {
        --fl-bg-dark: #1e2226 !important;        /* Dark Slate Canvas */
        --fl-panel-bg: #282d33 !important;       /* Panel Background */
        --fl-panel-header: #31373e !important;   /* Header / Rack Dark */
        --fl-accent-green: #20d67a !important;   /* FL Emerald Green */
        --fl-accent-orange: #ff7034 !important;  /* FL Orange Highlight */
        --fl-border: #14171a !important;         /* Dark Border Dividers */
        --fl-text-main: #d0d7de !important;      /* Crisp Light Grey Text */
        --fl-text-muted: #7d8b99 !important;     /* Muted Grey Text */
    }

    /* --- Overall Page Background --- */
    body, 
    div[class*="main"], 
    div[class*="studio"], 
    .mix-editor {
        background-color: var(--fl-bg-dark) !important;
        color: var(--fl-text-main) !important;
        font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, sans-serif !important;
    }

    /* --- Top Navigation / Toolbar (FL Channel Rack Style) --- */
    header, 
    nav, 
    div[class*="navbar"], 
    div[class*="top-bar"] {
        background-color: var(--fl-panel-header) !important;
        border-bottom: 2px solid var(--fl-border) !important;
        box-shadow: 0 2px 5px rgba(0,0,0,0.4) !important;
    }

    /* --- Transport Controls & Buttons (Play, Record, Loop) --- */
    button[class*="play"], 
    div[class*="play"] {
        color: var(--fl-accent-green) !important;
    }

    button[class*="record"], 
    div[class*="record"] {
        color: var(--fl-accent-orange) !important;
    }

    /* --- Track Headers & Mixer Channels --- */
    div[class*="track-header"], 
    div[class*="channel"], 
    div[class*="mixer-strip"] {
        background-color: var(--fl-panel-bg) !important;
        border-right: 1px solid var(--fl-border) !important;
        border-bottom: 1px solid var(--fl-border) !important;
        border-radius: 2px !important;
    }

    /* --- Selected Track Highlight --- */
    div[class*="track-header"][class*="selected"], 
    div[class*="track"][class*="active"] {
        background-color: #38404a !important;
        border-left: 4px solid var(--fl-accent-orange) !important;
    }

    /* --- Volume Meters & Progress Bars --- */
    div[class*="meter-bar"], 
    progress, 
    div[class*="progress"] {
        background-color: var(--fl-accent-green) !important;
        box-shadow: 0 0 6px rgba(32, 214, 122, 0.5) !important;
    }

    /* --- Knobs, Sliders & Control Handles --- */
    input[type="range"]::-webkit-slider-thumb {
        background: var(--fl-accent-orange) !important;
        border: 1px solid #000 !important;
    }

    input[type="range"]::-moz-range-thumb {
        background: var(--fl-accent-orange) !important;
        border: 1px solid #000 !important;
    }

    /* --- Buttons and Dropdown Menus --- */
    button, 
    .btn, 
    div[role="button"] {
        background-color: var(--fl-panel-header) !important;
        color: var(--fl-text-main) !important;
        border: 1px solid var(--fl-border) !important;
        border-radius: 3px !important;
        transition: all 0.15s ease-in-out !important;
    }

    button:hover, 
    .btn:hover, 
    div[role="button"]:hover {
        background-color: #3d454f !important;
        color: #ffffff !important;
        border-color: var(--fl-accent-green) !important;
    }

    /* --- Grid / Arrangement View (FL Playlist Vibe) --- */
    div[class*="grid"], 
    div[class*="timeline"], 
    canvas {
        background-color: #171a1d !important;
    }

    /* Grid Lines Accent */
    div[class*="grid-line"], 
    div[class*="ruler"] {
        border-color: rgba(255, 255, 255, 0.05) !important;
    }

    /* --- Modals, Popups & Sidebars --- */
    div[class*="modal"], 
    div[class*="sidebar"], 
    div[class*="drawer"] {
        background-color: var(--fl-panel-bg) !important;
        border: 1px solid var(--fl-border) !important;
        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6) !important;
    }

    /* --- Scrollbars (FL Flat Sleek Style) --- */
    ::-webkit-scrollbar {
        width: 8px !important;
        height: 8px !important;
        background-color: var(--fl-bg-dark) !important;
    }

    ::-webkit-scrollbar-thumb {
        background-color: var(--fl-panel-header) !important;
        border-radius: 4px !important;
        border: 1px solid var(--fl-border) !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background-color: var(--fl-accent-orange) !important;
    }
}
